INSERT INTO product_lines (id, manufacturer_id, name, code, description, origin_type, status_code) VALUES
(10, 8, 'Kits de Aluminio AL Industria', 'AL-KITS', 'Kit Sacada sem Rolamento, Kit Pia 6/8mm, Kit Box 8mm, Kit Box Reto 8mm, Kit Engenharia 8mm e 10mm -- perfis de secao (sem peso informado no catalogo, so dimensoes de secao) mais os descontos/folgas de vao citados literalmente: Kit Pia: portas = vao - 40mm (pag.39). Kit Box / Kit Box Reto: fixo = vao - 55mm, porta = vao - 20mm (pag.40). Kit Engenharia 8mm: fixo = vao - 60mm, correr = vao - 20mm (pag.41). Kit Engenharia 10mm: fixo = vao - 65mm, correr = vao - 25mm (pag.41). Kit Sacada sem Rolamento: folga na altura = vao menor - 200mm; folga na largura = 30mm (15mm cada lateral) + 3mm por juncao de vidro; peso maximo do vidro 8mm+acessorios = 25kg/m2, vidro 10mm+acessorios = 30kg/m2 (pag.35). Estes descontos NAO foram carregados como formula_deductions porque nao ha typology/formula_version correspondente cadastrada ainda -- ficam documentados aqui e em docs/FONTES.md para uso futuro.', 'ENCONTRADO_DOCUMENTO', 'CATALOGADO');
